const{div:div,span:span,anchor:anchor,heading:heading,paragraph:paragraph,text:text}=jsonDomComponents,columns=4,tileContent=t=>anchor(t.href,[div([span([text(t.title[0].toUpperCase())],"tile-icon-letter")],"tile-icon"),heading(3,[text(t.title)]),paragraph(t.description)],"tile-link",{target:"_blank"}),projectGrid=t=>{const e=Math.ceil(t.length/4),a=matrixDom.buildMatrix({x:4,y:e,z:1},{matrix:{attributes:{className:"project-grid"}},x:{attributes:{className:"tile tile-empty"}}});return t.forEach((t,e)=>{const i=matrixDom.getDomItemFromPoint(matrixDom.point(e%4,Math.floor(e/4)),a);i.attributes.className="tile",jsonDom.appendChild(i,tileContent(t))}),a};export default projectGrid;